        /// Sync a store into a Meta catalog Keeps a Meta product catalog in sync with the store, for catalog ads (&#x60;goal: catalog_sales&#x60;) and Shops. The first full run starts right away in the background; &#x60;runStatus&#x60; and the item counts report its outcome. Every active product variant that is published to the online store and has an image becomes a catalog item, grouped by product (&#x60;item_group_id&#x60;). After that, product changes on the store update the catalog within minutes, and a daily full run removes items for products or variants the store no longer has. Items are namespaced to the store, so a catalog can take several stores and a run never touches items it did not create.  &#x60;catalogAccountId&#x60; is a connected facebook, instagram or metaads account whose Meta login can manage the catalog (the catalog_management permission); find catalogs with &#x60;GET /v1/ads/catalogs&#x60;. 
